UPDATE chat_file_delivery d SET pending_until = now() FROM chat_message m
WHERE d.message_id = m.id AND m.group_id = #{groupId} AND m.sender_user_id = #{senderId}
  AND m.id = #{messageId} AND d.attempt_id = #{attemptId}

mapper.select:
SELECT page.id, page.sender_user_id, page.sender_nickname, page.type, page.content, page.created_at, page.attachment_id, page.attachment_content_type, page.attachment_width, page.attachment_height, page.attachment_byte_size, page.attachment_file_name, page.sender_avatar, page.sender_deleted_at, page.transfer_status FROM ( WHERE m.group_id = #{groupId} AND m.type = 'FILE' AND m.id IN
#{id,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}
) page ORDER BY page.sequence_number

SELECT attachment.id, attachment.content_type, attachment.data FROM chat_attachment attachment
JOIN chat_message message ON message.id = attachment.message_id
WHERE message.group_id = #{groupId} AND attachment.id = #{attachmentId}
